namespace WebApi.Entities;

/// <summary>
/// ST-35 F3: one proposed metadata change for a song, generated by the background review job
/// and resolved (accepted/rejected) by the user from the songs list. A song's row shows a
/// Review button while it has pending proposals.
/// </summary>
public class MetadataProposal
{
    public Guid Id { get; set; }
    public Guid SongId { get; set; }
    public Song? Song { get; set; }

    /// <summary>Which field: "title" | "artist" | "genre" | "year" | "key" | "tempo".</summary>
    public string Field { get; set; } = null!;

    /// <summary>The song's value when the proposal was made (display + staleness check).</summary>
    public string? CurrentValue { get; set; }

    public string ProposedValue { get; set; } = null!;

    /// <summary>"pending" | "accepted" | "rejected".</summary>
    public string Status { get; set; } = "pending";

    public DateTime CreatedAt { get; set; }
    public DateTime? ResolvedAt { get; set; }
}
